require 'json'; m=Sketchup.active_model; r=->(v){(v.to_m*100).round/100.0}; pt=->(v,t){ p=v.position.transform(t); [r.(p.x),r.(p.y),r.(p.z)] }; inst=[]; los=[]; walk=nil; walk=->(ents,t,pad){ ents.each{|e| if e.is_a?(Sketchup::Face) then los << {'pad'=>pad,'c'=>(e.material ? e.material.color.to_a[0,3] : nil),'p'=>e.outer_loop.vertices.map{|v| pt.(v,t)},'gaten'=>e.loops.reject(&:outer?).map{|l| l.vertices.map{|v| pt.(v,t)}}} elsif e.is_a?(Sketchup::Group)||e.is_a?(Sketchup::ComponentInstance) then n=e.definition.name; tt=t*e.transformation; inst << {'pad'=>pad,'n'=>n,'naam'=>e.name.to_s,'groep'=>e.is_a?(Sketchup::Group),'m'=>tt.to_a,'verborgen'=>(e.hidden? || !e.layer.visible?)}; walk.(e.definition.entities, tt, pad+[e.name.to_s.empty? ? n : e.name.to_s]) unless n.include?('·') end }}; walk.(m.entities, Geom::Transformation.new, []); f='G:/Mijn Drive/Projecten/hexgrid city concept/raatstad-berg-alles.json'; File.write(f, JSON.generate({'bestand'=>m.path,'instanties'=>inst,'los'=>los})); puts "klaar: #{inst.size} groepen en componenten, #{los.size} losse vlakken"
